import * as React from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { Input, type InputProps } from '@/components/ui/input'
import { Popover, PopoverAnchor, PopoverContent } from '@/components/ui/popover'
import { useControllableState, useDebouncedValue } from '@/components/ui/util'
import { cn } from '@/lib/utils'
export interface AutoCompleteProps extends Omit<InputProps, 'onChange' | 'value' | 'defaultValue'> {
  options: string[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  loadOptions?: (query: string, signal: AbortSignal) => Promise<string[]>
  renderOption?: (value: string) => React.ReactNode
  virtual?: boolean
  searchable?: boolean
}
export function AutoComplete({
  options,
  value,
  defaultValue = '',
  onValueChange,
  loadOptions,
  renderOption,
  virtual,
  searchable = true,
  ...props
}: AutoCompleteProps) {
  const [text, setText] = useControllableState({ value, defaultValue, onChange: onValueChange }),
    [open, setOpen] = React.useState(false),
    [remote, setRemote] = React.useState<string[]>([]),
    [loading, setLoading] = React.useState(false),
    [error, setError] = React.useState(''),
    [active, setActive] = React.useState(0)
  const query = useDebouncedValue(text),
    id = React.useId(),
    scroll = React.useRef<HTMLDivElement>(null),
    input = React.useRef<HTMLInputElement>(null)
  React.useEffect(() => {
    if (!open || !loadOptions) return
    const controller = new AbortController()
    setLoading(true)
    setError('')
    loadOptions(query, controller.signal)
      .then((data) => {
        if (!controller.signal.aborted) setRemote(data)
      })
      .catch((e) => {
        if (!controller.signal.aborted) setError(String(e))
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [query, loadOptions, open])
  const filtered = React.useMemo(
      () =>
        loadOptions
          ? remote
          : searchable
            ? options.filter((option) => option.toLowerCase().includes(text.toLowerCase()))
            : options,
      [loadOptions, remote, options, text, searchable],
    ),
    virtualized = virtual ?? filtered.length > 100,
    list = useVirtualizer({
      count: filtered.length,
      getScrollElement: () => scroll.current,
      estimateSize: () => 36,
      overscan: 4,
      enabled: open && virtualized,
      initialRect: { width: 280, height: 250 },
    })
  const choose = (option: string) => {
    setText(option)
    setOpen(false)
    input.current?.focus()
  }
  const render = (index: number, start?: number) => (
    <div
      key={index}
      id={`${id}-${index}`}
      role="option"
      aria-selected={active === index}
      className={cn('cursor-pointer rounded px-3 py-2 text-sm', active === index && 'bg-accent')}
      style={
        start === undefined
          ? undefined
          : { position: 'absolute', top: start, height: 36, width: '100%' }
      }
      onPointerMove={() => setActive(index)}
      onMouseDown={(e) => e.preventDefault()}
      onClick={() => choose(filtered[index])}
    >
      {renderOption?.(filtered[index]) ?? filtered[index]}
    </div>
  )
  return (
    <Popover open={open && !props.disabled} onOpenChange={setOpen}>
      <PopoverAnchor asChild>
        <Input
          {...props}
          ref={input}
          role="combobox"
          aria-autocomplete="list"
          aria-expanded={open}
          aria-controls={id}
          aria-activedescendant={open && filtered[active] ? `${id}-${active}` : undefined}
          value={text}
          onFocus={() => setOpen(true)}
          onValueChange={(next) => {
            setText(next)
            setActive(0)
            setOpen(true)
          }}
          onKeyDown={(event) => {
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
              event.preventDefault()
              setOpen(true)
              const next =
                (active + (event.key === 'ArrowDown' ? 1 : filtered.length - 1)) %
                Math.max(1, filtered.length)
              setActive(next)
              list.scrollToIndex(next)
            }
            if (event.key === 'Enter' && open && filtered[active]) {
              event.preventDefault()
              choose(filtered[active])
            }
            if (event.key === 'Escape') setOpen(false)
            props.onKeyDown?.(event)
          }}
        />
      </PopoverAnchor>
      <PopoverContent
        align="start"
        className="w-[var(--radix-popover-trigger-width)] min-w-56 p-1"
        onOpenAutoFocus={(e) => e.preventDefault()}
        onInteractOutside={(e) => {
          if (input.current?.contains(e.target as Node)) e.preventDefault()
        }}
        onCloseAutoFocus={(e) => e.preventDefault()}
      >
        <div
          ref={scroll}
          id={id}
          role="listbox"
          className="max-h-64 overflow-auto"
          style={virtualized ? { height: Math.min(250, filtered.length * 36) } : undefined}
        >
          {loading ? (
            <p role="status" className="p-3 text-sm">
              Loading suggestions…
            </p>
          ) : error ? (
            <p role="alert" className="p-3 text-sm text-destructive">
              {error}
            </p>
          ) : filtered.length ? (
            virtualized ? (
              <div className="relative" style={{ height: list.getTotalSize() }}>
                {list.getVirtualItems().map((item) => render(item.index, item.start))}
              </div>
            ) : (
              filtered.map((_, index) => render(index))
            )
          ) : (
            <p className="p-3 text-sm text-muted-foreground">No suggestions.</p>
          )}
        </div>
      </PopoverContent>
    </Popover>
  )
}

import * as React from 'react'
import { Eye, EyeOff, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useControllableState } from '@/components/ui/util'
export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
  leading?: React.ReactNode
  trailing?: React.ReactNode
  allowClear?: boolean
  showCount?: boolean
  passwordToggle?: boolean
  onValueChange?: (value: string) => void
}
export function Input({
  className,
  type = 'text',
  value,
  defaultValue = '',
  onChange,
  onValueChange,
  leading,
  trailing,
  allowClear,
  showCount,
  passwordToggle,
  ref,
  ...props
}: InputProps) {
  const [current, setCurrent] = useControllableState<string>({
    value: value === undefined ? undefined : String(value),
    defaultValue: String(defaultValue),
    onChange: onValueChange,
  })
  const [reveal, setReveal] = React.useState(false),
    input = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => input.current!)
  const field = (
    <input
      {...props}
      ref={input}
      type={passwordToggle && reveal ? 'text' : type}
      data-slot="input"
      value={current}
      onChange={(event) => {
        setCurrent(event.target.value)
        onChange?.(event)
      }}
      className={cn(
        'h-9 w-full min-w-0 rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30 aria-invalid:border-destructive',
        leading && 'pl-9',
        (trailing || allowClear || passwordToggle) && 'pr-10',
        className,
      )}
    />
  )
  if (!leading && !trailing && !allowClear && !showCount && !passwordToggle) return field
  return (
    <span className="relative inline-flex w-full flex-col">
      <span className="relative flex w-full items-center">
        {leading && <span className="absolute left-3 z-1 text-muted-foreground">{leading}</span>}
        {field}
        <span className="absolute right-2 flex items-center gap-1 text-muted-foreground">
          {allowClear && current && !props.disabled && (
            <button
              type="button"
              aria-label="Clear input"
              onClick={() => {
                const element = input.current
                if (!element) return
                Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set?.call(
                  element,
                  '',
                )
                element.dispatchEvent(new Event('input', { bubbles: true }))
                setCurrent('')
                element.focus()
              }}
            >
              <X size={14} />
            </button>
          )}
          {passwordToggle && (
            <button
              type="button"
              aria-label={reveal ? 'Hide password' : 'Show password'}
              onClick={() => setReveal((v) => !v)}
            >
              {reveal ? <EyeOff size={15} /> : <Eye size={15} />}
            </button>
          )}
          {trailing}
        </span>
      </span>
      {showCount && (
        <span className="mt-1 self-end text-[10px] text-muted-foreground">
          {current.length}
          {props.maxLength ? ` / ${props.maxLength}` : ''}
        </span>
      )}
    </span>
  )
}
export function OTPInput({
  value,
  defaultValue = '',
  onValueChange,
  length = 6,
  disabled,
  pattern = /\d/,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (code: string) => void
  length?: number
  disabled?: boolean
  pattern?: RegExp
}) {
  const [code, setCode] = useControllableState({ value, defaultValue, onChange: onValueChange })
  const refs = React.useRef<(HTMLInputElement | null)[]>([])
  const clean = (text: string) =>
    Array.from(text)
      .filter((char) => {
        pattern.lastIndex = 0
        return pattern.test(char)
      })
      .join('')
      .slice(0, length)
  return (
    <div
      role="group"
      aria-label="One-time code"
      className="flex gap-2"
      onPaste={(e) => {
        e.preventDefault()
        const text = clean(e.clipboardData.getData('text'))
        setCode(text)
        refs.current[Math.min(text.length, length - 1)]?.focus()
      }}
    >
      {Array.from({ length }, (_, index) => (
        <input
          key={index}
          ref={(el) => {
            refs.current[index] = el
          }}
          aria-label={`Code digit ${index + 1}`}
          inputMode="numeric"
          autoComplete={index === 0 ? 'one-time-code' : 'off'}
          value={code[index] ?? ''}
          disabled={disabled}
          maxLength={1}
          className="h-11 w-9 rounded-lg border bg-background text-center font-mono text-lg outline-ring"
          onChange={(e) => {
            const char = clean(e.target.value).slice(-1)
            setCode((code.slice(0, index) + char + code.slice(index + 1)).slice(0, length))
            if (char) refs.current[Math.min(index + 1, length - 1)]?.focus()
          }}
          onKeyDown={(e) => {
            if (e.key === 'Backspace') {
              if (!code[index]) refs.current[Math.max(0, index - 1)]?.focus()
              else setCode(code.slice(0, index) + code.slice(index + 1))
            }
            if (e.key === 'ArrowLeft') refs.current[Math.max(0, index - 1)]?.focus()
            if (e.key === 'ArrowRight') refs.current[Math.min(length - 1, index + 1)]?.focus()
          }}
        />
      ))}
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Popover as PopoverPrimitive } from 'radix-ui'

function Popover({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal container={usePortalContainer()}>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          'z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

function PopoverAnchor({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="popover-header"
      className={cn('flex flex-col gap-1 text-sm', className)}
      {...props}
    />
  )
}

function PopoverTitle({ className, ...props }: React.ComponentProps<'h2'>) {
  return <div data-slot="popover-title" className={cn('font-medium', className)} {...props} />
}

function PopoverDescription({ className, ...props }: React.ComponentProps<'p'>) {
  return (
    <p
      data-slot="popover-description"
      className={cn('text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverAnchor,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}
